text:
Browse full tracklists, album runtimes, and artwork.




&lt;label for="artist-select"&gt;Artist&lt;/label&gt;
&lt;select id="artist-select" class="control-select"&gt;&lt;/select&gt;


&lt;label for="album-select"&gt;Album&lt;/label&gt;
&lt;select id="album-select" class="control-select"&gt;&lt;/select&gt;




&lt;img id="album-cover-img" class="album-cover" src="" alt="Album Artwork"&gt;
&lt;div class="album-meta"&gt;
  &lt;h3 id="album-title-text" class="album-title-text"&gt;&lt;/h3&gt;
  &lt;p id="album-artist-text" class="album-artist-text"&gt;&lt;/p&gt;
  &lt;div class="badge-row"&gt;
    &lt;span id="badge-year" class="meta-badge"&gt;&lt;/span&gt;
    &lt;span id="badge-tracks" class="meta-badge"&gt;&lt;/span&gt;
  &lt;/div&gt;
&lt;/div&gt;


&lt;div class="tracklist-container"&gt;
  &lt;div id="track-list" class="track-list"&gt;&lt;/div&gt;
&lt;/div&gt;
